/** Generate the initial app route manifest seed. */
export function generateRouteManifestSeed(): string {
  return [
    '// This file is seeded by netscript init and regenerated by @netscript/fresh/vite.',
    '',
    'export const routePatterns = {',
    "  $route: '/',",
    '  dashboard: {',
    "    $route: '/dashboard',",
    '  },',
    '  health: {',
    "    $route: '/health',",
    '  },',
    '  examples: {',
    "    $route: '/examples',",
    '    crud: {',
    "      $route: '/examples/crud',",
    '    },',
    '    orders: {',
    '      $id: {',
    "        $route: '/examples/orders/[id]',",
    '      },',
    '    },',
    '    telemetry: {',
    "      $route: '/examples/telemetry',",
    '    },',
    '  },',
    '  design: {',
    "    $route: '/design',",
    '    tokens: {',
    "      $route: '/design/tokens',",
    '    },',
    '    components: {',
    "      $route: '/design/components',",
    '    },',
    '    composition: {',
    "      $route: '/design/composition',",
    '    },',
    '  },',
    '} as const;',
    '',
  ].join('\n');
}

/** Generate the initial typed route reference seed. */
export function generateRoutesSeed(): string {
  return [
    '// This file is seeded by netscript init and regenerated by @netscript/fresh/vite.',
    '',
    "import { createRouteReference } from '@netscript/fresh/route';",
    "import { routePatterns } from './manifest.ts';",
    '',
    'export const routes = {',
    '  $route: createRouteReference(routePatterns.$route, {',
    "    id: 'home',",
    "    kind: 'page',",
    '  }),',
    '  dashboard: {',
    '    $route: createRouteReference(routePatterns.dashboard.$route, {',
    "      id: 'dashboard',",
    "      kind: 'page',",
    '    }),',
    '  },',
    '  health: {',
    '    $route: createRouteReference(routePatterns.health.$route, {',
    "      id: 'health',",
    "      kind: 'page',",
    '    }),',
    '  },',
    '  examples: {',
    '    $route: createRouteReference(routePatterns.examples.$route, {',
    "      id: 'examples',",
    "      kind: 'page',",
    '    }),',
    '    crud: {',
    '      $route: createRouteReference(routePatterns.examples.crud.$route, {',
    "        id: 'examples.crud',",
    "        kind: 'page',",
    '      }),',
    '    },',
    '    orders: {',
    '      $id: {',
    '        $route: createRouteReference(routePatterns.examples.orders.$id.$route, {',
    "          id: 'examples.orders.$id',",
    "          kind: 'page',",
    '        }),',
    '      },',
    '    },',
    '    telemetry: {',
    '      $route: createRouteReference(routePatterns.examples.telemetry.$route, {',
    "        id: 'examples.telemetry',",
    "        kind: 'page',",
    '      }),',
    '    },',
    '  },',
    '  design: {',
    '    $route: createRouteReference(routePatterns.design.$route, {',
    "      id: 'design',",
    "      kind: 'page',",
    '    }),',
    '    tokens: {',
    '      $route: createRouteReference(routePatterns.design.tokens.$route, {',
    "        id: 'design.tokens',",
    "        kind: 'page',",
    '      }),',
    '    },',
    '    components: {',
    '      $route: createRouteReference(routePatterns.design.components.$route, {',
    "        id: 'design.components',",
    "        kind: 'page',",
    '      }),',
    '    },',
    '    composition: {',
    '      $route: createRouteReference(routePatterns.design.composition.$route, {',
    "        id: 'design.composition',",
    "        kind: 'page',",
    '      }),',
    '    },',
    '  },',
    '} as const;',
    '',
  ].join('\n');
}
